/* globe-photo-data.js
 * The Earth by day and by night, as data inside a script, so the photo
 * globe also works when the page is opened straight from disk.
 * Day: NASA Blue Marble. Night: NASA Black Marble. Both public domain.
 */
(function (root) {
  'use strict';
  var LJ = (root.LJ = root.LJ || {});
  LJ.globePhoto = {
    day: 'data:image/jpeg;base64,',
    night: 'data:image/jpeg;base64,'
  };
})(window);
